// Протерміновані задачі → по одному item'у на відповідального з готовою HTML-таблицею. Немає задач — немає items і листів.
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const day = s => s ? String(s).slice(0, 10) : '—';
const groups = {};
for (const task of items[0]?.result ?? []) {
  if (!task.responsibleId) continue; // у Кіті відповідальний обов'язковий
  (groups[task.responsibleId] ??= { responsibleId: task.responsibleId, tasks: [] }).tasks.push(task);
}
return Object.values(groups).map(g => {
  g.tasks.sort((a, b) => String(a.deadline).localeCompare(String(b.deadline)));
  const rows = g.tasks.map(t => '<tr><td>' + esc(t.title) + '</td><td>' + day(t.deadline) + '</td></tr>').join('');
  return { ...g, count: g.tasks.length, html: '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Задача</th><th>Дедлайн</th></tr>' + rows + '</table>' };
});

// Зведення для кожного керівника (з профілю відповідального): усі його люди з протермінованими задачами.
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const groups = $node["Менеджер і задачі"].all;
const byManager = {};
items.forEach((item, i) => {
  if (!item.found || !item.manager?.email) return;
  const group = groups[i];
  const who = group.user?.name || 'Відповідальний ' + (group.responsibleId ?? 'не вказаний');
  const entry = byManager[item.manager.email] ??= { email: item.manager.email, name: item.manager.name, total: 0, rows: [] };
  entry.total += group.count;
  entry.rows.push('<tr><td>' + esc(who) + '</td><td>' + group.count + '</td></tr>');
});
return Object.values(byManager).map(m => ({ email: m.email, name: m.name, total: m.total,
  html: '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Менеджер</th><th>Протерміновано</th></tr>' + m.rows.join('') + '</table>' }));
